// Validate input parameters and prepare context
const input = $input.first().json;
const body = input.body || input;
const startTime = Date.now();

const guildId = body.guild_id || null;
const userId = body.user_id || null;
const threadId = body.thread_id || null;
const includeHistory = body.include_history !== false; // default true
const historyLimit = body.history_limit || 10;

const errors = [];
if (!guildId) errors.push('guild_id');
if (!userId) errors.push('user_id');
if (!threadId) errors.push('thread_id');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Missing required parameters: ${errors.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Validate history_limit is a positive number
if (historyLimit < 1 || historyLimit > 100) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'history_limit must be between 1 and 100',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    guild_id: guildId,
    user_id: userId,
    thread_id: threadId,
    include_history: includeHistory,
    history_limit: historyLimit,
    start_time: startTime,
    // Redis key for session store
    session_key: `discord:session:${guildId}:${userId}:${threadId}`,
    // Backend endpoint for student info
    student_key: `discord:student:${guildId}:${userId}`
  }
}];

// Tag student info result
const result = $input.first().json;
return {
  json: {
    source: 'student',
    data: result
  }
};

// Tag session history result
const result = $input.first().json;
return {
  json: {
    source: 'history',
    data: result
  }
};

// Tag subject context result
const result = $input.first().json;
return {
  json: {
    source: 'subject',
    data: result
  }
};

// Build enriched context from all data sources
const items = $input.all();
const inputData = $('Validate Input').first().json;
const startTime = inputData.start_time;
const historyLimit = inputData.history_limit;
const includeHistory = inputData.include_history;

// Find results by source tag
let studentData = null;
let historyData = null;
let subjectData = null;

for (const item of items) {
  const source = item.json.source;
  const data = item.json.data;

  if (source === 'student') {
    studentData = data;
  } else if (source === 'history') {
    historyData = data;
  } else if (source === 'subject') {
    subjectData = data;
  }
}

// Parse student info from Redis
let student = {
  name: 'Etudiant',
  promo: 'Non defini',
  enrolled_at: null
};

try {
  const rawStudent = studentData?.propertyName || studentData?.value || studentData;
  if (rawStudent && rawStudent !== null) {
    const parsed = typeof rawStudent === 'string' ? JSON.parse(rawStudent) : rawStudent;
    student = {
      name: parsed.name || parsed.discord_username || 'Etudiant',
      promo: parsed.promo || parsed.promotion_name || 'Non defini',
      enrolled_at: parsed.enrolled_at || parsed.joined_at || null,
      discord_user_id: parsed.discord_user_id || inputData.user_id,
      discord_username: parsed.discord_username || null
    };
  }
} catch (e) {
  // Keep defaults
}

// Parse subject context from Redis
let currentSubject = {
  slug: null,
  name: 'Contexte general'
};

try {
  const rawSubject = subjectData?.propertyName || subjectData?.value || subjectData;
  if (rawSubject && rawSubject !== null) {
    const parsed = typeof rawSubject === 'string' ? JSON.parse(rawSubject) : rawSubject;
    currentSubject = {
      slug: parsed.slug || parsed.subject_slug || null,
      name: parsed.name || parsed.subject_name || 'Contexte general',
      expert_id: parsed.expert_id || null
    };
  }
} catch (e) {
  // Keep defaults
}

// Parse conversation history from Redis (RedisSessionStore format)
let conversationHistory = [];

if (includeHistory) {
  try {
    const rawHistory = historyData?.propertyName || historyData?.value || historyData;
    if (rawHistory && rawHistory !== null) {
      const parsed = typeof rawHistory === 'string' ? JSON.parse(rawHistory) : rawHistory;

      // Handle RedisSessionStore format: { messages: [...] } or direct array
      const messages = Array.isArray(parsed) ? parsed : (parsed.messages || parsed.history || []);

      // Get last N messages based on history_limit
      conversationHistory = messages.slice(-historyLimit).map(msg => ({
        role: msg.role || (msg.is_user ? 'user' : 'assistant'),
        content: msg.content || msg.text || msg.message || '',
        timestamp: msg.timestamp || msg.created_at || null
      }));
    }
  } catch (e) {
    // Keep empty history
  }
}

// Build personalized prompt context
let promptContext = `Tu parles a ${student.name}`;
if (student.promo && student.promo !== 'Non defini') {
  promptContext += `, etudiant en ${student.promo}`;
}
if (student.enrolled_at) {
  const enrollDate = new Date(student.enrolled_at);
  const monthsEnrolled = Math.floor((Date.now() - enrollDate.getTime()) / (1000 * 60 * 60 * 24 * 30));
  if (monthsEnrolled > 0) {
    promptContext += ` (inscrit depuis ${monthsEnrolled} mois)`;
  }
}
promptContext += '.';

if (currentSubject.slug) {
  promptContext += ` Le contexte actuel est la matiere "${currentSubject.name}".`;
}

if (conversationHistory.length > 0) {
  promptContext += ` Tu as deja eu ${conversationHistory.length} echange(s) avec cet etudiant dans cette session.`;
}

// Calculate latency
const latencyMs = Date.now() - startTime;

// Build response
const response = {
  success: true,
  data: {
    student: student,
    current_subject: currentSubject,
    conversation_history: conversationHistory,
    prompt_context: promptContext
  },
  _trace: {
    service_response: {
      student: studentData,
      history: historyData,
      subject: subjectData
    },
    sources: ['redis:student', 'redis:session', 'redis:subject'],
    parallel: true,
    latency_ms: latencyMs
  }
};

return { json: response };

